BEGIN;
CREATE TABLE auth_sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON auth_sessions(user_id);
CREATE TABLE verification_tokens (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE platform_admins (user_id uuid PRIMARY KEY REFERENCES users(id));
CREATE TABLE store_settings (store_id uuid PRIMARY KEY REFERENCES stores(id),contact_phone text NOT NULL DEFAULT '',pickup_address text NOT NULL DEFAULT '',shipping_fee_idr bigint NOT NULL DEFAULT 0 CHECK(shipping_fee_idr>=0),pickup_enabled boolean NOT NULL DEFAULT true,delivery_enabled boolean NOT NULL DEFAULT false,bank_details text NOT NULL DEFAULT '',qris_media_key text,policies text NOT NULL DEFAULT '',accent text NOT NULL DEFAULT '#171715',hero_title text NOT NULL DEFAULT '',hero_image_url text,logo_url text,opening_hours text NOT NULL DEFAULT '',low_stock_threshold integer NOT NULL DEFAULT 5 CHECK(low_stock_threshold>=0));
ALTER TABLE orders ADD COLUMN request_hash text NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN tracking_token_hash text;
ALTER TABLE orders ADD COLUMN tracking_expires_at timestamptz;
ALTER TABLE orders ADD COLUMN tracking_token_sealed text;
ALTER TABLE orders ADD COLUMN shipment_reference text;
CREATE UNIQUE INDEX ON orders(tracking_token_hash);
CREATE TABLE rate_limits (key text PRIMARY KEY,window_start timestamptz NOT NULL DEFAULT now(),hits int NOT NULL DEFAULT 0);
CREATE TABLE usage_counters (store_id uuid NOT NULL REFERENCES stores(id),feature_code text NOT NULL,period_key text NOT NULL,value bigint NOT NULL DEFAULT 0 CHECK(value>=0),PRIMARY KEY(store_id,feature_code,period_key));
ALTER TABLE store_subscriptions ADD COLUMN grace_days int NOT NULL DEFAULT 7 CHECK(grace_days BETWEEN 0 AND 30);
CREATE UNIQUE INDEX one_current_subscription ON store_subscriptions(store_id) WHERE status IN ('trial','active','past_due','grace');
ALTER TABLE subscription_invoices ADD COLUMN idempotency_key text UNIQUE;
ALTER TABLE subscription_invoices ADD COLUMN verified_by uuid REFERENCES users(id);
CREATE SEQUENCE subscription_invoice_counter;
ALTER TABLE custom_project_leads ADD COLUMN source_ownership text NOT NULL DEFAULT 'pending' CHECK(source_ownership IN ('pending','nalaro_license','client_owned','mixed'));
ALTER TABLE custom_project_leads ADD COLUMN reusable_modules text NOT NULL DEFAULT '';
ALTER TABLE custom_project_leads ADD COLUMN contract_terms text NOT NULL DEFAULT '';
ALTER TABLE custom_project_leads ADD COLUMN quote_idr bigint CHECK(quote_idr>=0);
ALTER TABLE custom_project_leads ADD COLUMN delivery_status text NOT NULL DEFAULT 'not_started' CHECK(delivery_status IN ('not_started','in_progress','review','delivered'));
CREATE UNIQUE INDEX active_interval_price ON plan_prices(plan_id,billing_interval) WHERE is_active;
CREATE UNIQUE INDEX invoice_period_unique ON subscription_invoices(subscription_id,period_start,period_end) WHERE status<>'void';
CREATE INDEX ON verification_tokens(expires_at);
CREATE INDEX ON inventory_movements(store_id,created_at);
CREATE INDEX ON manual_payment_reviews(store_id,order_id);
COMMIT;
